# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"
require "securerandom"
require "yaml"

RSpec.describe Invoices::PreparedReservations do
  include PreparedReservationsSpecSupport

  context "commit and abort under another company" do
    let(:owning_company) { create(:company) }
    let(:intruding_company) { create(:company) }
    let(:owning_client) { create(:client, company: owning_company) }
    let(:owning_project) { create(:project, client: owning_client) }
    let(:entry_user) { create(:user) }

    before do
      TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    end

    def cross_company_rows(invoice_id)
      ApplicationRecord.connection.select_rows(ApplicationRecord.sanitize_sql_array([
        "SELECT company_id, entry_id, state, disposition FROM reservations WHERE invoice_id = ? ORDER BY entry_id", invoice_id
      ]))
    end

    def cross_company_operation_state(invoice_id)
      ApplicationRecord.connection.select_value(ApplicationRecord.sanitize_sql_array([
        "SELECT state FROM invoice_operations WHERE invoice_id = ?", invoice_id
      ]))
    end

    it "a commit or abort sent under another company never touches a prepared operation that shares its invoice and operation ids" do
      entry = Timekeeping::LocalEntry.create!(company_id: owning_company.id, user_id: entry_user.id,
                                              project_id: owning_project.id, work_date: Date.current,
                                              duration: 30.0, bill_status: "unbilled")
      invoice = create(:invoice, company: owning_company, client: owning_client)
      operation_id = SecureRandom.uuid
      request_for = lambda do |company_id|
        Invoices::ReservationRequest.new(
          company_id:, invoice_id: invoice.id, operation_id:,
          generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [entry.id]
        )
      end
      adapter = described_class.new
      expect(adapter.prepare(request_for.call(owning_company.id)).state).to eq("prepared")
      rows_before = cross_company_rows(invoice.id)
      outbox_before = Timekeeping::LocalOutboxEntry.where(entry_id: entry.id).count
      version_before = entry.reload.version

      # "Store the operation identity on each reservation row, so commit and abort touch only their own rows"
      adapter.commit(request_for.call(intruding_company.id))
      adapter.abort(request_for.call(intruding_company.id))

      expect(cross_company_rows(invoice.id)).to eq(rows_before)
      expect(rows_before).to eq([[owning_company.id, entry.id, "provisional", "active"]])
      expect(cross_company_operation_state(invoice.id)).to eq("prepared")
      expect(Timekeeping::LocalOutboxEntry.where(entry_id: entry.id).count).to eq(outbox_before)
      expect(entry.reload.version).to eq(version_before)

      expect(adapter.commit(request_for.call(owning_company.id)).state).to eq("committed")
      expect(cross_company_rows(invoice.id)).to eq([[owning_company.id, entry.id, "committed", "active"]])
    end
  end

  context "locked change outbox row" do
    let(:outbox_data_company) { create(:company) }
    let(:outbox_data_user) { create(:user, current_workspace_id: outbox_data_company.id) }
    let(:outbox_data_project) { create(:project, client: create(:client, company: outbox_data_company)) }

    before do
      TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    end

    it "a locked change raises the entry version once and writes exactly one contract-shaped outbox row, and turning provisional to committed writes none" do
      entry = Timekeeping::LocalEntry.create!(company_id: outbox_data_company.id, user_id: outbox_data_user.id,
                                              project_id: outbox_data_project.id, work_date: Date.new(2026, 3, 2),
                                              duration: 60.0, bill_status: "unbilled")
      version_before = entry.reload.version
      request = Invoices::ReservationRequest.new(
        company_id: outbox_data_company.id, invoice_id: 91_301, operation_id: SecureRandom.uuid,
        generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [entry.id]
      )
      adapter = described_class.new
      outbox = Timekeeping::LocalOutboxEntry.where(company_id: outbox_data_company.id, entry_id: entry.id)

      adapter.prepare(request)

      # "When an entry's locked state changes, update the matching row in the prepared `entries` table, raise its
      # version, and write an `entry_outbox_items` row shaped by `contracts/timekeeping/entry_snapshots.yml`, as the
      # fake's `refresh_locked` does."
      expect(outbox.count).to eq(1)
      expect(entry.reload.version).to eq(version_before + 1)
      contract_fields = YAML.safe_load_file(Rails.root.join("contracts/timekeeping/entry_snapshots.yml")).fetch("entry_fields")
      payload = outbox.first.payload
      payload = JSON.parse(payload) if payload.is_a?(String)
      expect(payload.keys).to match_array(contract_fields)
      expect(payload["locked"]).to be(true)

      adapter.commit(request)

      expect(outbox.count).to eq(1)
      expect(entry.reload.version).to eq(version_before + 1)
    end
  end

  context "tenant boundary on abort and commit" do
    it "abort by one company with a shared operation id leaves another company's provisional reservation, which still commits" do
      TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
      generation = TimekeepingOwnership.current.generation
      shared_operation_id = SecureRandom.uuid
