        )
        invoice = create(:invoice, company:, client:)
        request = Invoices::ReservationRequest.new(
          company_id: company.id, invoice_id: invoice.id, operation_id: shared_operation_id,
          generation:, disposition: "active", entries: [entry.id]
        )
        { company:, entry:, request: }
      end
      company_a_setup, company_b_setup = setups
      adapter = described_class.new

      expect(adapter.prepare(company_b_setup[:request]).state).to eq("prepared")
      expect(adapter.prepare(company_a_setup[:request]).state).to eq("prepared")

      # "Store the operation identity on each reservation row, so commit and abort touch only their own rows (docs/solutions/design-patterns/carry-scoped-operation-identity-into-owned-rows.md)."
      expect(adapter.abort(company_a_setup[:request]).state).to eq("aborted")

      reservation_rows = lambda do |setup|
        ApplicationRecord.connection.select_rows(ApplicationRecord.sanitize_sql_array([
          "SELECT company_id, entry_id, state FROM reservations WHERE entry_id = ?", setup[:entry].id
        ]))
      end
      expect(reservation_rows.call(company_a_setup)).to eq([])
      expect(reservation_rows.call(company_b_setup))
        .to eq([[company_b_setup[:company].id, company_b_setup[:entry].id, "provisional"]])

      expect(adapter.commit(company_b_setup[:request]).state).to eq("committed")
      expect(reservation_rows.call(company_b_setup))
        .to eq([[company_b_setup[:company].id, company_b_setup[:entry].id, "committed"]])
      expect(reservation_rows.call(company_a_setup)).to eq([])
